// Historical context; relief probabilities remain game rules.
public static class DiplomaticChronicles
{
    public sealed class Profile { public string Religion; public bool Orthodox; public string[] Paragraphs; public Profile(string religion,bool orthodox,string[] paragraphs) {Religion=religion;Orthodox=orthodox;Paragraphs=paragraphs;} }
    public static readonly Profile[] All={
        new Profile("Catholic",false,new[]{"Hungary holds the middle Danube, where royal towns and fortified river crossings face the Ottoman advance. Its great captains have fought the Sultan's armies before; the defeats at Varna and Kosovo remain fresh wounds.","The crown belongs to the Latin Church. Bishops, magnates and military households can all answer a call to defend Christendom, although they seldom agree on who should pay for it.","A surviving Constantinople would occupy Ottoman armies far from Hungary's southern frontier. Yet another distant expedition risks men needed at home. Your envoy must offer a strategic opportunity as well as a Christian appeal."}),
        new Profile("Catholic",false,new[]{"Venice governs from a lagoon, but her fortunes sail across the eastern sea. Merchants, island governors and naval officers watch the straits through which their grain and cargoes must pass.","The republic worships in the Latin rite. Her colonies include many Orthodox Christians, and her Senate weighs commercial privilege alongside religious obligation.","Venetians already share the City's danger. Relief would defend their people and trading routes, but raising a fleet takes orders, money and time. The Senate must be persuaded that Constantinople can hold until its ships arrive."}),
        new Profile("Catholic",false,new[]{"Genoa's merchants reach from the Ligurian coast to the ports of the Black Sea. Powerful families and colonial officers pursue interests of their own; an agreement with the republic does not settle every quarrel in Galata.","Genoa is Catholic, while her trading settlements live among Greeks, Armenians and other communities. Shared faith with Rome binds her less tightly than a single banner might suggest.","Genoese volunteers can defend Constantinople while their countrymen negotiate with the Sultan. Secure passage, colonial possessions and the fate of Galata all matter. A policy that wins one Genoese captain may alarm another."}),
        new Profile("Catholic",false,new[]{"Pope Nicholas V rules a territorial state in Italy and speaks to princes far beyond it. Rome possesses money, envoys and spiritual authority; the armies of Christendom remain in other hands.","The papacy seeks the fulfilment of the Union of Florence. Communion with Rome gives an appeal for aid greater force, while the City's opposition to union troubles its advocates.","The Pope can send funds and ships and urge rulers to act. He cannot make every king abandon his own war. A successful embassy must turn declarations of Christian duty into supplies aboard vessels already preparing to sail."}),
        new Profile("Catholic",false,new[]{"Skanderbeg's Albanian resistance holds mountain strongholds against Ottoman power. Its strength rests on local knowledge, fighting households and alliances that must repeatedly be renewed.","Skanderbeg's diplomacy looks towards Catholic Italy. Albania itself contains Catholic, Orthodox and Muslim communities; allegiance and survival cut across these divisions.","The City and the Albanian lords face the same expanding enemy. An Ottoman reverse here would help them, but every experienced fighter sent abroad is absent from a vulnerable homeland. Even a small contingent would be a costly commitment."}),
        new Profile("Catholic",false,new[]{"The Hospitallers began as a brotherhood caring for pilgrims in Jerusalem, then acquired a military role in the crusader states. After losing their foothold in the Holy Land, they established themselves on Rhodes in the early fourteenth century. The fortified island now sits astride the eastern sea routes. Their ships and garrisons give a small order a reach far beyond its numbers.","The brothers are a Catholic military order under religious vows, sustained by a wider network of European houses and estates. Their identity combines armed service with the care of the sick; a hospital and a fortress belong to the same institution. They govern an island with a substantial Greek Orthodox population, whose labour and cooperation sustain the fortress.","Constantinople is close enough for Rhodian ships to matter. The Order must also guard its own island and sea lanes. Your appeal competes with the Grand Master's duty to keep Rhodes ready for the next attack."}),
        new Profile("Catholic",false,new[]{"Alfonso's Naples is a southern Italian kingdom joined by its ruler to wider Aragonese ambitions. Its ports can gather ships, troops and money for ventures in the eastern Mediterranean.","The monarchy is Catholic. Crusading language sits comfortably beside dynastic claims and the ambitions of a court that remembers older Latin enterprises in Greek lands.","Alfonso has reason to resist Ottoman expansion and to seek influence in the East. Assistance would bring obligations as well as soldiers. Your envoys must win a commitment without promising away the independence they hope to save."}),
        new Profile("Catholic",false,new[]{"Frederick III bears the imperial title, but the German lands contain princes, bishops and cities with treasuries and armies of their own. An imperial appeal must travel through many councils before it becomes a marching column.","The Emperor and most of these rulers belong to the Latin Church. Religious divisions in the wider imperial world, especially over Bohemia, complicate any claim to effortless Christian unity.","Constantinople's cause can command sympathy and prestige. Distance, divided authority and the cost of assembling an expedition make prompt relief difficult. A modest force or a purse of money is easier to secure than the whole strength of the Empire."}),
        new Profile("Catholic",false,new[]{"Charles VII's France is recovering land and authority after generations of war with England. Its captains have experience, but its towns and countryside have paid dearly for their victories.","France is Catholic, with a proud crown and an influential clergy. Royal policy guards the king's authority even when Rome calls for common action.","A crusading enterprise could bring honour, but the eastern sea lies far beyond the king's immediate concerns. Ships, passage and provisioning must all be arranged. A French promise is valuable only if the City can survive the long journey that follows."}),
        new Profile("Catholic court",false,new[]{"The duchy of Athens survives under the Florentine Acciaioli house, ruling from the ancient city and its fortified heights. Its small court lives among stronger neighbours and unsettled succession politics.","The ruling dynasty is Catholic; much of the population follows the Orthodox Church. A ducal decision therefore speaks for a government rather than a single religious community.","Ottoman pressure leaves Athens little freedom of action, and its relations with the Roman rulers of the Morea have also been hostile. Fear of the Sultan might inspire secret assistance, but it can just as easily compel refusal."}),
        new Profile("Orthodox",true,new[]{"Georgia stretches across mountain valleys and routes between the Black Sea and the lands beyond the Caucasus. King George VIII must contend with powerful regional lords as well as enemies on his borders.","The Georgian Church is Orthodox, with its own language, traditions and ancient monasteries. Communion with the Greeks gives your embassy a language of shared sacred duty.","Constantinople's survival would preserve an important Christian power on the western sea. Yet Georgia's own divisions and the long journey limit what its king can promise. Volunteers and supplies are more plausible than an army stripped from its frontier."}),
        new Profile("Orthodox",true,new[]{"Trebizond clings to the southern shore of the Black Sea, where the Grand Komnenoi maintain an imperial court amid mountains, ports and caravan routes. Its wealth exceeds the breadth of its territory.","Its dynasty and Church are Orthodox. Imperial ancestry and Greek learning connect it to Constantinople, despite centuries of separate rule and competing claims.","The fall of your City would leave Trebizond more exposed. Its merchants can send provisions and its court can offer men, but the route runs through seas increasingly threatened by Ottoman power. Sympathy does not remove that danger."}),
        new Profile("Catholic court",false,new[]{"John II's Cyprus is a Lusignan kingdom whose ports link the Levant with the Aegean. Genoese power at Famagusta and tribute owed to Egypt weigh heavily on the crown.","The royal house is Catholic, while most islanders are Orthodox. Queen Helena Palaiologina brings a close connection to the Greek imperial world and its religious life.","These ties give Constantinople friends at court. Money, ships and political freedom remain scarce. Aid must be assembled without provoking the powers already pressing upon the island."}),
        new Profile("Catholic crown",false,new[]{"Casimir rules Poland and Lithuania through a union of crowns and interests, each with its own institutions and powerful lords. Their lands reach from the Baltic approaches deep into the Ruthenian world.","Poland is Catholic. Lithuania's ruling house has adopted Catholic Christianity within living memory, while many of its eastern subjects are Orthodox. The dynasty governs across these traditions rather than erasing them.","The death of Casimir's brother at Varna gives Ottoman expansion a personal place in the dynasty's memory. Checking the Sultan could serve its interests, but Baltic disputes and a very long road compete with your appeal. A distant king's goodwill must still become a usable expedition."}),
        new Profile("Catholic",false,new[]{"The Teutonic Order holds a fortified state in Prussia, built around castles, estates and Baltic commerce. Its towns and nobles increasingly challenge the burdens imposed by their masters.","The brothers are a Catholic military order. Their old crusading identity has become entangled with disputes against Christian neighbours and subjects.","An eastern expedition offers a return to a celebrated religious purpose, but the Order cannot lightly weaken its troubled homeland. Money and a small body of volunteers are more conceivable than the departure of its principal army."}),
        new Profile("Catholic",false,new[]{"Henry VI's England is burdened by the long French war and rivalries among great households. Resources raised for distant victories have brought disappointments home.","The English crown and Church are Catholic. Pilgrimage, crusading memory and devotion can make the City's appeal intelligible even at this distance.","English archers would be welcome on your walls. Getting them here requires money, ships and passage across several seas, while the crown faces urgent demands of its own. An expedition would depend as much on determined patrons as on royal sympathy."}),
        new Profile("Muslim",false,new[]{"Ibrahim Bey rules Karaman, an Anatolian principality centred on Konya and Larende. Its dynasty competes with the Ottomans for influence, routes and towns across central and southern Anatolia. A powerful Sultan threatens its room to manoeuvre even when the two courts are formally at peace.","Karaman is a Muslim power with its own rulers, religious foundations and political ambitions. Shared faith with the Ottomans does not erase their rivalry. Its merchants trade with Christian as well as Muslim neighbours; grain, horses and other goods give diplomacy practical substance.","Your envoys can appeal to Ibrahim's interest in preventing an Ottoman victory from making Mehmed stronger. Open intervention would be dangerous, but discreet money and provisions offer a smaller commitment. In this campaign that possibility is represented by an uncertain relief package, not a claim that Karaman historically sent an expedition to rescue Constantinople."}),
    };
    public static string Article(int index) {
        var ally=CouncilActions.Allies[index];
        return string.Join("\n\n",All[index].Paragraphs)+"\n\n<color=#E8C36F>In your campaign</color>\nA successful appeal commits "+ally.Cargo+". The expedition normally takes "+ally.Days+" days to reach the City. Acceptance depends on the court, your diplomatic focus and advisers; the Papacy also weighs your religious policy.";
    }
}